const weapons=[{name:'Iron sword',attack:22,speed:1.6},{name:'Obsidian axe',attack:40,speed:1},{name:'Wind blades',attack:16,speed:2.3},{name:'Crystal spear',attack:29,speed:1.4}];
const armors=[{name:'Leather armor',defense:12,hp:20},{name:'Knight armor',defense:45,hp:100},{name:'Shadow armor',defense:24,hp:45},{name:'Dragon armor',defense:60,hp:160}];
const presets=[{name:'Berserker',strength:40,dexterity:15,vitality:15,weapon:1,armor:0},{name:'Guardian',strength:15,dexterity:10,vitality:45,weapon:0,armor:3},{name:'Assassin',strength:20,dexterity:40,vitality:10,weapon:2,armor:2}];
let builds=[{...presets[0],level:20},{...presets[1],level:20}];
const budget=b=>30+b.level*2;
function valid(b){return b&&Number.isInteger(b.level)&&b.level>=1&&b.level<=50&&['strength','dexterity','vitality'].every(k=>Number.isInteger(b[k])&&b[k]>=0)&&b.strength+b.dexterity+b.vitality<=budget(b)&&Number.isInteger(b.weapon)&&!!weapons[b.weapon]&&Number.isInteger(b.armor)&&!!armors[b.armor]}
try{const s=JSON.parse(localStorage.getItem('shady-build-forge-v1'));if(Array.isArray(s)&&s.length===2&&s.every(valid))builds=s}catch{}
function calculate(b){const w=weapons[b.weapon],a=armors[b.armor],attack=w.attack+b.strength*2,crit=Math.min(.6,.05+b.dexterity*.006),speed=w.speed*(1+b.dexterity*.01),hp=100+b.vitality*12+a.hp,defense=a.defense+b.vitality*.5;return{dps:attack*speed*(1+crit*.5),hp,ehp:hp*(1+defense/100),crit:crit*100,defense,attack,speed}}
const fmt=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:1}).format(n);
function notify(t){const e=document.querySelector('#toast');e.textContent=t;e.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.style.display='none',2600)}
function render(){document.querySelector('#builds').innerHTML=builds.map((b,i)=>`<article class="card"><div class="card-head"><span class="badge">${i?'B':'A'}</span><div><h2>Build ${i?'B':'A'}</h2><p class="sub">Your next strategy</p></div></div><label for="preset${i}">Choose a playstyle</label><select id="preset${i}" data-i="${i}" data-key="preset"><option value="">Custom build</option>${presets.map((p,j)=>`<option value="${j}">${p.name}</option>`).join('')}</select><div class="section-title">01 / CHARACTER</div><div class="level"><label for="level${i}">Character level</label><input id="level${i}" type="number" min="1" max="50" value="${b.level}" data-i="${i}" data-key="level"></div>${[['strength','Strength'],['dexterity','Dexterity'],['vitality','Vitality']].map(([k,label])=>`<div class="attr-label"><label for="${k}${i}">${label}</label><b id="value-${k}${i}">${b[k]}</b></div><input id="${k}${i}" type="range" min="0" max="${budget(b)}" value="${b[k]}" data-i="${i}" data-key="${k}">`).join('')}<div class="points" id="points${i}"></div><div class="section-title">02 / EQUIPMENT</div>${[['weapon','Weapon',weapons],['armor','Armor',armors]].map(([k,label,items])=>`<label for="${k}${i}">${label}</label><select id="${k}${i}" data-i="${i}" data-key="${k}">${items.map((item,j)=>`<option value="${j}" ${b[k]===j?'selected':''}>${item.name}</option>`).join('')}</select><div class="equipment-note" id="note-${k}${i}"></div>`).join('')}<div class="mini-stats" id="stats${i}"></div></article>`).join('');update()}
function update(){const results=builds.map(calculate);builds.forEach((b,i)=>{const s=results[i];document.querySelector('#points'+i).textContent=`${budget(b)-b.strength-b.dexterity-b.vitality} / ${budget(b)} points available`;for(const k of ['strength','dexterity','vitality'])document.querySelector('#value-'+k+i).textContent=b[k];document.querySelector('#stats'+i).innerHTML=`<div><small>AVERAGE DPS</small><strong>${fmt(s.dps)}</strong></div><div><small>HEALTH</small><strong>${fmt(s.hp)}</strong></div>`;const w=weapons[b.weapon],a=armors[b.armor];document.querySelector('#note-weapon'+i).textContent=`${w.attack} base attack · ${w.speed} attacks/sec`;document.querySelector('#note-armor'+i).textContent=`${a.defense} defense · +${a.hp} health`});document.querySelector('#comparison').innerHTML=[['dps','Damage per second',''],['hp','Health',''],['ehp','Effective health',''],['crit','Critical chance','%']].map(([k,label,unit])=>{const a=results[0][k],b=results[1][k],diff=(b/a-1)*100,max=Math.max(a,b);return `<div class="metric"><div class="metric-top"><span>${label}</span><strong>B ${diff>=0?'+':''}${fmt(diff)}%</strong></div><div class="bar"><span style="width:${a/max*100}%"></span></div><div class="bar b"><span style="width:${b/max*100}%"></span></div><div class="legend"><span>A · ${fmt(a)}${unit}</span><span>B · ${fmt(b)}${unit}</span></div></div>`}).join('');const [a,b]=results;document.querySelector('#insight').textContent=Math.abs(a.dps-b.dps)<.01&&Math.abs(a.ehp-b.ehp)<.01?'Both builds have equal damage and durability. Change an attribute or item to explore the difference.':`Build ${a.dps>=b.dps?'A':'B'} deals more average damage. Build ${a.ehp>=b.ehp?'A':'B'} absorbs more incoming damage in this demo model.`}
document.querySelector('#builds').addEventListener('input',e=>{const el=e.target,k=el.dataset.key;if(!k)return;const i=Number(el.dataset.i),b=builds[i];if(k==='preset'){if(el.value==='')return;builds[i]={...presets[Number(el.value)],level:20};render();return}let n=Number(el.value);if(!Number.isFinite(n))return;n=Math.round(n);if(k==='level'){b.level=Math.min(50,Math.max(1,n));let left=budget(b);for(const a of ['strength','dexterity','vitality']){b[a]=Math.min(b[a],left);left-=b[a]}render();return}if(['strength','dexterity','vitality'].includes(k)){const available=budget(b)-['strength','dexterity','vitality'].filter(a=>a!==k).reduce((sum,a)=>sum+b[a],0);n=Math.min(available,Math.max(0,n));el.value=n}b[k]=n;document.querySelector('#preset'+i).value='';update()});
document.querySelector('#save').onclick=()=>{try{localStorage.setItem('shady-build-forge-v1',JSON.stringify(builds));notify('Both builds have been saved in this browser.')}catch{notify('Browser storage unavailable. Export JSON to keep your builds.')}};
document.querySelector('#copy').onclick=()=>{builds[1]={...builds[0]};render();notify('Build A has been copied to B.')};
document.querySelector('#reset').onclick=()=>{builds=[{...presets[0],level:20},{...presets[1],level:20}];render();notify('Default builds restored.')};
document.querySelector('#export').onclick=()=>{const data={project:'Shady Build Forge',version:1,model:'Demonstration only; not official Minecraft MMORPG balance',builds:builds.map(b=>({...b,weapon:weapons[b.weapon],armor:armors[b.armor],results:calculate(b)}))};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='shady-builds.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Builds exported.')};render();
